// Locale map (originally generated by merge_all.py, which is not in this repo;
// the English fallback below is hand-written). en.json is the source of truth
// and its shape defines the Dictionary type; other locales may lag it.

import en from "./dictionaries/en.json";
import es from "./dictionaries/es.json";
import am from "./dictionaries/am.json";
import ha from "./dictionaries/ha.json";
import yo from "./dictionaries/yo.json";
import sw from "./dictionaries/sw.json";
import ta from "./dictionaries/ta.json";
import te from "./dictionaries/te.json";
import mr from "./dictionaries/mr.json";
import pa from "./dictionaries/pa.json";
import my from "./dictionaries/my.json";
import bn from "./dictionaries/bn.json";
import hi from "./dictionaries/hi.json";
import vi from "./dictionaries/vi.json";
import id from "./dictionaries/id.json";
import th from "./dictionaries/th.json";
import tr from "./dictionaries/tr.json";
import uk from "./dictionaries/uk.json";
import ru from "./dictionaries/ru.json";
import ko from "./dictionaries/ko.json";
import ja from "./dictionaries/ja.json";
import zh from "./dictionaries/zh.json";
import de from "./dictionaries/de.json";
import fr from "./dictionaries/fr.json";
import it from "./dictionaries/it.json";
import pt from "./dictionaries/pt.json";
import ar from "./dictionaries/ar.json";
import fa from "./dictionaries/fa.json";
import ur from "./dictionaries/ur.json";
import { DEFAULT_LOCALE } from "./config";

export type Dictionary = typeof en;

// Other locales may lack keys English has (see withEnglish below), hence the
// cast through unknown: they are only ever read after the English merge.
const DICTIONARIES: Record<string, Dictionary> = {
  en,
  es: es as unknown as Dictionary,
  am: am as unknown as Dictionary,
  ha: ha as unknown as Dictionary,
  yo: yo as unknown as Dictionary,
  sw: sw as unknown as Dictionary,
  ta: ta as unknown as Dictionary,
  te: te as unknown as Dictionary,
  mr: mr as unknown as Dictionary,
  pa: pa as unknown as Dictionary,
  my: my as unknown as Dictionary,
  bn: bn as unknown as Dictionary,
  hi: hi as unknown as Dictionary,
  vi: vi as unknown as Dictionary,
  id: id as unknown as Dictionary,
  th: th as unknown as Dictionary,
  tr: tr as unknown as Dictionary,
  uk: uk as unknown as Dictionary,
  ru: ru as unknown as Dictionary,
  ko: ko as unknown as Dictionary,
  ja: ja as unknown as Dictionary,
  zh: zh as unknown as Dictionary,
  de: de as unknown as Dictionary,
  fr: fr as unknown as Dictionary,
  it: it as unknown as Dictionary,
  pt: pt as unknown as Dictionary,
  ar: ar as unknown as Dictionary,
  fa: fa as unknown as Dictionary,
  ur: ur as unknown as Dictionary,
};

/**
 * English fills any key a locale does not have yet. New copy lands in en.json
 * first and the translation lane backfills the other locales later ("whatever
 * is missing"); until it has, those keys read in English rather than as
 * undefined. Objects merge key by key; strings and arrays are taken whole.
 */
function withEnglish<T>(base: T, local: unknown): T {
  if (local === undefined || local === null) return base;
  if (typeof base !== "object" || base === null || Array.isArray(base)) return local as T;
  if (typeof local !== "object" || Array.isArray(local)) return base;
  const out: Record<string, unknown> = { ...(base as Record<string, unknown>) };
  for (const [k, v] of Object.entries(local as Record<string, unknown>)) {
    out[k] = k in out ? withEnglish(out[k], v) : v;
  }
  return out as T;
}

const MERGED = new Map<string, Dictionary>();

export function getDictionary(locale: string): Dictionary {
  const local = DICTIONARIES[locale];
  if (!local || locale === DEFAULT_LOCALE) return DICTIONARIES[DEFAULT_LOCALE];
  let d = MERGED.get(locale);
  if (!d) {
    d = withEnglish(DICTIONARIES[DEFAULT_LOCALE], local);
    MERGED.set(locale, d);
  }
  return d;
}
